import{_ as e}from"./chunks/report.8JoF_Gem.js";import{_ as r,o as d,c as a,a2 as o}from"./chunks/framework.DbZkMlmv.js";const m=JSON.parse('{"title":"Understanding Results","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/results.md","filePath":"en/guide/results.md"}'),i={name:"en/guide/results.md"};function s(n,t,l,c,h,u){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="understanding-results" tabindex="-1">Understanding Results <a class="header-anchor" href="#understanding-results" aria-label="Permalink to &quot;Understanding Results&quot;">​</a></h1><h2 id="global-risk-score" tabindex="-1">Global risk score <a class="header-anchor" href="#global-risk-score" aria-label="Permalink to &quot;Global risk score&quot;">​</a></h2><p>Each scan produces a <strong>risk score from 0 to 100</strong>, calculated by weighting findings by severity:</p><table tabindex="0"><thead><tr><th>Level</th><th>Weight</th><th>Meaning</th></tr></thead><tbody><tr><td>🔴 CRITICAL</td><td>×10</td><td>Immediately exploitable vulnerability</td></tr><tr><td>🟠 HIGH</td><td>×5</td><td>High risk, urgent fix required</td></tr><tr><td>🟡 MEDIUM</td><td>×2</td><td>Moderate risk, fix soon</td></tr><tr><td>🔵 LOW</td><td>×1</td><td>Low risk, best practice</td></tr><tr><td>ℹ️ INFO</td><td>×0</td><td>Informational, no direct risk</td></tr></tbody></table><p>The overall level is determined as follows:</p><table tabindex="0"><thead><tr><th>Score</th><th>Level</th></tr></thead><tbody><tr><td>0</td><td>✅ SAFE</td></tr><tr><td>1 - 30</td><td>🔵 LOW</td></tr><tr><td>31 - 60</td><td>🟡 MEDIUM</td></tr><tr><td>61 - 85</td><td>🟠 HIGH</td></tr><tr><td>86 - 100</td><td>🔴 CRITICAL</td></tr></tbody></table><p><img src="'+e+'" alt="Scan report"></p><h2 id="report-structure" tabindex="-1">Report structure <a class="header-anchor" href="#report-structure" aria-label="Permalink to &quot;Report structure&quot;">​</a></h2><p>The report is organized into <strong>tabs per scanner</strong>. Each tab shows:</p><ul><li>The number of findings by severity</li><li>Finding details: affected file, line number, description, recommendation</li></ul><h2 id="npm-version-check" tabindex="-1">NPM version check <a class="header-anchor" href="#npm-version-check" aria-label="Permalink to &quot;NPM version check&quot;">​</a></h2><p>The <strong>NPM</strong> tab compares dependencies with the latest version published on npm. When a lock file is present, its resolved version takes precedence as the comparison baseline.</p><table tabindex="0"><thead><tr><th>Difference</th><th>Severity</th><th>Code</th></tr></thead><tbody><tr><td>Major (<code>x</code> → <code>y</code>)</td><td>🔴 HIGH</td><td><code>NPM_OUTDATED</code></td></tr><tr><td>Minor (<code>x.y</code> → <code>x.z</code>)</td><td>🟡 MEDIUM</td><td><code>NPM_OUTDATED</code></td></tr><tr><td>Patch (<code>x.y.z</code> → <code>x.y.w</code>)</td><td>🔵 LOW</td><td><code>NPM_OUTDATED</code></td></tr></tbody></table><p>The update table shows the current version, latest available version, and the source used for the comparison.</p><h2 id="version-ui5" tabindex="-1">Version ui5 <a class="header-anchor" href="#version-ui5" aria-label="Permalink to &quot;Version ui5&quot;">​</a></h2><p>Detailed view of the ui5 x.x.x version, with data from <a href="https://ui5.sap.com/" target="_blank" rel="noreferrer">https://ui5.sap.com/</a> :</p><ul><li>Librairies,</li><li>Composants,</li><li>Themes.</li></ul>',17)])])}const f=r(i,[["render",s]]);export{m as __pageData,f as default};
